/** Actual OpportunityModal; response states generated by the real C3 API/publisher
 * fixture. Browser traffic is fulfilled; no live server, provider or mutation. */
import { expect, test } from '@playwright/test'
import { build } from 'esbuild'
import { readFileSync } from 'node:fs'
import { resolve } from 'node:path'
const FIX = JSON.parse(readFileSync(new URL('./fixtures/cioReviewLifecycle.fixture.json', import.meta.url), 'utf8'))
let js = '', css = ''
test.beforeAll(async () => {
  const result = await build({
    stdin: { contents: `import React from 'react'; import {createRoot} from 'react-dom/client'; import OpportunityModal from './src/components/opportunity/OpportunityModal'; import './src/index.css'; createRoot(document.getElementById('root')).render(<OpportunityModal symbol="TSLA" onClose={()=>{}}/>);`, loader: 'tsx', resolveDir: process.cwd() },
    bundle: true, write: false, outdir: '/virtual-c3-fixture', format: 'iife', define: { 'process.env.NODE_ENV': '"production"' },
    loader: { '.woff2': 'dataurl', '.woff': 'dataurl', '.svg': 'dataurl' },
  })
  js = result.outputFiles!.find(f => f.path.endsWith('.js'))!.text
  css = result.outputFiles!.find(f => f.path.endsWith('.css'))!.text
})
for (const width of [1440, 412]) for (const phase of ['requested', 'answered', 'resolved', 'resolved_stale']) {
  test(`actual modal ${phase} at ${width}`, async ({ page }) => {
    await page.setViewportSize({ width, height: 1050 })
    await page.clock.install({ time: new Date('2026-10-24T16:00:00Z') })
    const state = phase === 'resolved_stale' ? FIX.resolved : FIX[phase]
    const assessment = phase === 'resolved' ? FIX.canonical_assessment : FIX.assessment_snapshot
    const denied: string[] = []
    await page.route('**/*', async route => {
      const req = route.request(), u = new URL(req.url())
      if (u.origin !== 'http://c3.fixture.invalid' || req.method() !== 'GET') { denied.push(`${req.method()} ${u.pathname}`); await route.abort(); return }
      if (u.pathname === '/') { await route.fulfill({ status: 200, contentType: 'text/html', body: '<html><body><div id="root"></div></body></html>' }); return }
      if (u.pathname === '/api/v3/opportunities/TSLA') {
        await route.fulfill({ status: 200, contentType: 'application/json', body: JSON.stringify({ ok: true, symbol: 'TSLA', assessment: { ...assessment, factors: {}, factors_missing: [] }, profile: {}, position: {}, chart: [], news: [], catalysts: [], watchlist: { on_watchlist: true }, cio_review: state, thesis: phase.startsWith('resolved') ? FIX.published_thesis : null }) }); return
      }
      denied.push(`${req.method()} ${u.pathname}`); await route.abort()
    })
    await page.routeWebSocket('**/*', ws => { denied.push('websocket'); ws.close() })
    await page.goto('http://c3.fixture.invalid/')
    await page.addStyleTag({ content: css }); await page.addScriptTag({ content: js })
    const panel = page.getByTestId('cio-review-lifecycle')
    await expect(panel).toBeVisible()
    await expect(panel).toHaveAttribute('data-status', state.lifecycle.status)
    await expect(panel).toContainText(state.lifecycle.reason)
    await expect(panel).toContainText(state.lifecycle.request_id)
    if (phase.startsWith('resolved')) {
      await expect(panel).toContainText('Conflict resolved')
      await expect(panel).toContainText('WATCH → ADD')
      await expect(panel).toContainText('res-fixture')
      if (phase === 'resolved_stale') await expect(page.getByTestId('cio-review-assessment-drift')).toContainText('retained assessment WATCH')
      else {
        await expect(page.getByTestId('cio-review-assessment-drift')).toHaveCount(0)
        await expect(page.getByTestId('opportunity-assessment-state')).toContainText('Assessment ADD')
      }
      await expect(page.getByTestId('opportunity-modal')).toContainText('Cited filing resolves the outdated guidance conflict')
    } else {
      await expect(panel).toContainText('pending authoritative readback')
      await expect(page.getByTestId('opp-request-review')).toBeDisabled()
    }
    const rect = await panel.evaluate(el => ({ x: el.getBoundingClientRect().x, right: el.getBoundingClientRect().right, width: innerWidth, client: el.clientWidth, scroll: el.scrollWidth }))
    expect(rect.x).toBeGreaterThanOrEqual(0); expect(rect.right).toBeLessThanOrEqual(rect.width + 1)
    expect(rect.scroll).toBeLessThanOrEqual(rect.client + 1)
    expect(denied).toEqual([])
    if (process.env.C3_SHOTS_DIR) await page.screenshot({ path: resolve(process.env.C3_SHOTS_DIR, `${phase}-${width}.png`), fullPage: true })
  })
}
